import sys
from collections import deque

def count_distinct_strings(N, grid):
    def bfs(start):
        queue = deque([start])
        visited = set([start])
        paths = {start: [grid[start[0]][start[1]]]}

        while queue:
            x, y = queue.popleft()
            for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                nx, ny = x + dx, y + dy
                if 0 <= nx < 2 and 0 <= ny < N and (nx, ny) not in visited:
                    visited.add((nx, ny))
                    queue.append((nx, ny))
                    paths[(nx, ny)] = [p + grid[nx][ny] for p in paths[(x, y)]]

        return set(''.join(p) for p in paths.values())

    all_paths = set()
    for i in range(2):
        for j in range(N):
            all_paths.update(bfs((i, j)))

    return len(all_paths)

input = sys.stdin.read().split()
index = 0
P = int(input[index])
index += 1
results = []

for _ in range(P):
    N = int(input[index])
    index += 1
    grid = [input[index], input[index + 1]]
    index += 2
    results.append(count_distinct_strings(N, grid))

for result in results:
    print(result)
